import java.util.*;

// Teaching math: reference vs embedding vs derived read model for one brand
// logo shown on N products. Teaching numbers only (amozeshi), not benchmarks.
public class LogoMath {
    public static void main(String[] a) {
        double n = 100_000;      // products of one brand
        double rps = 800;        // product-page reads/s
        double lookupMs = 1.5;   // brand lookup cost
        double backfill = 2_000; // derived-view apply rate/s
        double budgetS = 5;      // acceptable freshness bound (teaching)

        double readTax = rps * lookupMs / 1000; // core-s per s
        double fanout = n;                       // sync-embed writes per change
        double mixedWindow = n / backfill;       // seconds of old/new mix
        long coverage = (long) (backfill * budgetS);

        System.out.println("read tax core-s/s (reference) = " + readTax);
        System.out.println("embed fan-out writes           = " + (long) fanout);
        System.out.println("mixed window s (embed)         = " + mixedWindow);
        System.out.println("lag-budget coverage (5 s)      = " + coverage);
        System.out.println("reference change cost          = 1 row");
        System.out.println("derived view                   = "
            + (long) fanout + " async versioned writes, resumable from cursor");

        String verdict;
        if (mixedWindow > budgetS * 4) {
            verdict = "VERDICT: sync embedding ruled out (50 s mix >> 5 s budget); "
                + "reference wins when freshness must be immediate, "
                + "versioned read model wins when 5 s lag is fine.";
        } else {
            verdict = "VERDICT: window fits the budget; embedding acceptable.";
        }
        System.out.println(verdict);
        System.out.println("OK");
    }
}
